begin;
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; end; $$;
create function pg_temp.denied(sql text) returns void language plpgsql as $$ begin begin execute sql; exception when others then return; end; raise exception 'expected denied'; end; $$;
insert into auth.users(id,email) values ('00000199-0000-4000-8000-000000000001','evidence-partner@example.invalid'),('00000199-0000-4000-8000-000000000002','evidence-admin@example.invalid');
insert into public.profiles(id,name,role) values ('00000199-0000-4000-8000-000000000001','Evidence Partner','PARTNER'),('00000199-0000-4000-8000-000000000002','Evidence Admin','ADMIN');
insert into public.partner_accounts(profile_id,login_id) values ('00000199-0000-4000-8000-000000000001','evidence-test-199');
insert into public.admin_accounts(profile_id,duty) values ('00000199-0000-4000-8000-000000000002','심사');
insert into storage.objects(bucket_id,name) values ('partner-qualifications','00000199-0000-4000-8000-000000000001/evidence/one.pdf'),('partner-qualifications','00000199-0000-4000-8000-000000000001/evidence/two.pdf');
select pg_temp.assert(not public.partner_evidence_enabled(),'notice gate default closed');
select pg_temp.denied($q$select public.submit_partner_evidence('00000199-0000-4000-8000-000000000001','QUALIFICATION','{"type":"Test"}','[{"path":"00000199-0000-4000-8000-000000000001/evidence/one.pdf","filename":"one.pdf","size":10}]')$q$);
update public.partner_evidence_release set enabled=true;
select public.submit_partner_evidence('00000199-0000-4000-8000-000000000001','COMPANION','{"hospital":"Test Agency","department":"Partner","duties":"Companion","startedOn":"2020-01-01","currentJob":true}','[{"path":"00000199-0000-4000-8000-000000000001/evidence/one.pdf","filename":"one.pdf","size":10},{"path":"00000199-0000-4000-8000-000000000001/evidence/two.pdf","filename":"two.pdf","size":10}]');
select pg_temp.assert(count(*)=2,'multiple file metadata') from public.partner_evidence_files;
select pg_temp.assert(kind='COMPANION' and status='PENDING' and current_job,'career kind and pending status') from public.partner_work_histories where partner_id='00000199-0000-4000-8000-000000000001';
select pg_temp.assert(not has_function_privilege('authenticated','public.submit_partner_evidence(uuid,text,jsonb,jsonb)','EXECUTE'),'browser cannot bypass binary validation');
select set_config('request.jwt.claims','{"sub":"00000199-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select pg_temp.denied('select public.open_partner_evidence((select id from public.partner_work_histories where partner_id=''00000199-0000-4000-8000-000000000001''),''HISTORY'',''test evidence review'')');
select set_config('request.jwt.claims','{"sub":"00000199-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select pg_temp.assert(not public.can_read_partner_evidence('00000199-0000-4000-8000-000000000001/evidence/one.pdf'),'reviewer needs reason audit first');
select public.open_partner_evidence(id,'HISTORY','test evidence review') from public.partner_work_histories where partner_id='00000199-0000-4000-8000-000000000001';
select pg_temp.assert(public.can_read_partner_evidence('00000199-0000-4000-8000-000000000001/evidence/one.pdf'),'audited file access');
delete from public.partner_work_histories where partner_id='00000199-0000-4000-8000-000000000001';
select pg_temp.assert(count(*)=2,'delete queues storage cleanup') from public.partner_evidence_deletions;
select pg_temp.assert(not public.can_read_partner_evidence('00000199-0000-4000-8000-000000000001/evidence/one.pdf'),'deleted metadata revokes reviewer access');
rollback;
